INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", "アヤネ", 10046, "2020/07/31 12:00:00", 2, 24001, 0.0, 401, 0.0, 0.0, 102301, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", "アヤネ", 10046, "2020/07/31 12:00:00", 1, 24002, 2.21, 402, 0.0, 0.0, 102301, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", "アヤネ", 10046, "2020/07/31 12:00:00", 2, 24003, 0.0, 403, 0.0, 0.0, 102301, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", "アサヒ", 10046, "2020/07/31 12:00:00", 2, 24004, 1.99, 701, 0.0, 0.0, 192201, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", "アサヒ", 10046, "2020/07/31 12:00:00", 1, 24005, 2.21, 702, 0.0, 0.0, 192201, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", "アサヒ", 10046, "2020/07/31 12:00:00", 2, 24006, 3.33, 703, 0.0, 0.0, 192201, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", "部員３", 10046, "2020/07/31 12:00:00", 2, 24007, 0.0, 801, 0.0, 0.0, 192301, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", "部員３", 10046, "2020/07/31 12:00:00", 1, 24008, 2.68, 802, 0.0, 0.0, 192301, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", "部員３", 10046, "2020/07/31 12:00:00", 2, 24009, 0.0, 803, 0.0, 0.0, 192301, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "やった！", "", 10046, "2020/07/31 12:00:00", 1, 24010, 0.0, 501, 0.0, 0.0, 192501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "勝ったよ！", "", 10046, "2020/07/31 12:00:00", 1, 24011, 0.0, 502, 0.0, 0.0, 192501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "いい調子！", "", 10046, "2020/07/31 12:00:00", 1, 24012, 0.0, 503, 0.0, 0.0, 192501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", "ミサト", 10046, "2020/07/31 12:00:00", 6, 24013, 5.33, 111, 0.0, 0.0, 113501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", "ミサト", 10046, "2020/07/31 12:00:00", 1, 24014, 6.85, 112, 0.0, 0.0, 113501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", "ミサト", 10046, "2020/07/31 12:00:00", 1, 24015, 3.0, 113, 0.0, 0.0, 113501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", "ダイチ", 10046, "2020/07/31 12:00:00", 1, 24016, 6.11, 611, 0.0, 0.0, 192401, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", "ダイチ", 10046, "2020/07/31 12:00:00", 1, 24017, 6.75, 612, 0.0, 0.0, 192401, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", "ダイチ", 10046, "2020/07/31 12:00:00", 2, 24018, 0.0, 613, 0.0, 0.0, 192401, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", "ハツネ", 10046, "2020/07/31 12:00:00", 2, 24019, 4.52, 211, 0.0, 0.0, 113401, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", "ハツネ", 10046, "2020/07/31 12:00:00", 2, 24020, 3.89, 212, 0.0, 0.0, 113401, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", "ハツネ", 10046, "2020/07/31 12:00:00", 1, 24021, 13.49, 213, 0.0, 0.0, 113401, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", "カヤ", 10046, "2020/07/31 12:00:00", 1, 24022, 3.17, 311, 0.0, 0.0, 106501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", "カヤ", 10046, "2020/07/31 12:00:00", 1, 24023, 4.42, 312, 0.0, 0.0, 106501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", "カヤ", 10046, "2020/07/31 12:00:00", 6, 24024, 2.89, 313, 0.0, 0.0, 106501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", "アヤネ", 10046, "2020/07/31 12:00:00", 4, 24025, 3.71, 421, 0.0, 0.0, 102301, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", "アサヒ", 10046, "2020/07/31 12:00:00", 2, 24026, 5.1, 721, 0.0, 0.0, 192201, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", "部員３", 10046, "2020/07/31 12:00:00", 1, 24027, 4.34, 821, 0.0, 0.0, 192301, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "いい勝負だったよ\nまたやろうね", "", 10046, "2020/07/31 12:00:00", 1, 24028, 0.0, 521, 0.0, 0.0, 192501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", "ミサト", 10046, "2020/07/31 12:00:00", 1, 24029, 5.62, 101, -360.0, 0.0, 113501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", "ミサト", 10046, "2020/07/31 12:00:00", 1, 24030, 9.58, 102, -360.0, 0.0, 113501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", "ミサト", 10046, "2020/07/31 12:00:00", 2, 24031, 0.0, 103, -360.0, 0.0, 113501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", "ミサト", 10046, "2020/07/31 12:00:00", 2, 24032, 9.13, 104, -360.0, 0.0, 113501, "2030/12/17 14:59:59", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", "ミサト", 10046, "2020/07/31 12:00:00", 1, 24033, 8.27, 105, -360.0, 0.0, 113501, "2030/12/17 14:59:59", 24);
